domain:
    # Image domain: width W (i), height H (j)
    i: dim in [0, W)      # column index
    j: dim in [0, H)      # row index

data:
    # Underlying C layout is img[W][H] with j (second index) fastest;
    # we model this as row-major with j contiguous:
    imgIn[i, j]:  in  DATA_TYPE = (i, j) -> i * H + j   # row-major, j fastest
    imgOut[i, j]: inout DATA_TYPE = (i, j) -> i * H + j # row-major, j fastest
    y1[i, j]:     tmp DATA_TYPE = (i, j) -> i * H + j   # row-major, j fastest
    y2[i, j]:     tmp DATA_TYPE = (i, j) -> i * H + j   # row-major, j fastest

parameters:
    alpha: DATA_TYPE          # IIR strength parameter
