    #
    # Mathematically, for i in [0,W):
    #   y1[i,j] = a5*z[i,j] + a6*z[i-1,j] + b1*y1[i-1,j] + b2*y1[i-2,j],
    #   with zero initial conditions for i < 0.
    #----------------------------------------------------------------------

    V_FWD:
        for j in [0, H):
            for i in seq([0, W)):         # sequential in i due to recurrence
                if i == 0:
                    y1[i, j] = a5 * z[i, j]
                elif i == 1:
                    y1[i, j] = a5 * z[i, j] +
                               a6 * z[i - 1, j] +
                               b1 * y1[i - 1, j]
                else:
                    y1[i, j] = a5 * z[i, j] +
                               a6 * z[i - 1, j] +
                               b1 * y1[i - 1, j] +
                               b2 * y1[i - 2, j]

    #----------------------------------------------------------------------
    # V_BWD: vertical backward recursion (bottom -> top) on each column.
    # Overwrites y2 with the vertical anti‑causal filter output.
    #
    # C loop:
    #   for j in [0,H):
    #     tp1=tp2=yp1=yp2=0;
    #     for i in [W-1..0]:
    #       y = a7*tp1 + a8*tp2 + b1*yp1 + b2*yp2;
    #       y2[i][j] = y;
    #       tp2=tp1; tp1=z[i][j]; yp2=yp1; yp1=y;
    #
    # Mathematically, for i in [0,W):
    #   y2[i,j] = a7*z[i+1,j] + a8*z[i+2,j] + b1*y2[i+1,j] + b2*y2[i+2,j],
    #   with z[W,j] = z[W+1,j] = 0 and y2[W,j] = y2[W+1,j] = 0.
    #----------------------------------------------------------------------

    V_BWD:
        for j in [0, H):
            for i in seq([0, W)):         # order constrained by dependencies below
                if i == W - 1:
                    y2[i, j] = (DATA_TYPE)0
                elif i == W - 2:
                    y2[i, j] = a7 * z[i + 1, j] +
                               b1 * y2[i + 1, j]
                else:
                    # i <= W-3, so i+1 and i+2 are in-bounds
                    y2[i, j] = a7 * z[i + 1, j] +
                               a8 * z[i + 2, j] +
                               b1 * y2[i + 1, j] +
                               b2 * y2[i + 2, j]

    #----------------------------------------------------------------------
    # COMB2: final pointwise combination, overwriting imgOut.
    #
    #   imgOut[i,j] = c2 * (y1[i,j] + y2[i,j])
    #
    # Corresponds to the second Halide Func combine2.
    #----------------------------------------------------------------------

    COMB2:
        for i in [0, W):
            for j in [0, H):
                imgOut[i, j] = c2 * (y1[i, j] + y2[i, j])

dependencies:
    # Horizontal forward recursion: left-to-right within each row.
    for i in [0, W), j in [1, H):
        H_FWD(i, j - 1) -> H_FWD(i, j)
    for i in [0, W), j in [2, H):
        H_FWD(i, j - 2) -> H_FWD(i, j)

    # Horizontal backward recursion: right-to-left within each row.
    for i in [0, W), j in [0, H - 1):
        H_BWD(i, j + 1) -> H_BWD(i, j)
    for i in [0, W), j in [0, H - 2):
        H_BWD(i, j + 2) -> H_BWD(i, j)

    # Vertical forward recursion: top-to-bottom within each column.
    for j in [0, H), i in [1, W):
        V_FWD(i - 1, j) -> V_FWD(i, j)
    for j in [0, H), i in [2, W):
        V_FWD(i - 2, j) -> V_FWD(i, j)

    # Vertical backward recursion: bottom-to-top within each column.
    for j in [0, H), i in [0, W - 1):
        V_BWD(i + 1, j) -> V_BWD(i, j)
    for j in [0, H), i in [0, W - 2):
        V_BWD(i + 2, j) -> V_BWD(i, j)

    # Stage ordering:
    #   1) H_FWD, H_BWD (row IIR on imgIn)
    #   2) COMB1 (z from y1,y2)
    #   3) V_FWD, V_BWD (column IIR on z)
    #   4) COMB2 (final imgOut)
    for i in [0, W), j in [0, H):
        H_FWD(i, j) -> COMB1(i, j)
        H_BWD(i, j) -> COMB1(i, j)

        COMB1(i, j) -> V_FWD(i, j)
        COMB1(i, j) -> V_BWD(i, j)

        V_FWD(i, j) -> COMB2(i, j)
        V_BWD(i, j) -> COMB2(i, j)

optimization:
    #--------------------------------------------------------------
    # 1. Parallelism across independent rows/columns
    #--------------------------------------------------------------
    # Horizontal passes (H_FWD, H_BWD):
    #   - rows i are independent; recurrences are only along j.
    #   - tile i into chunks and parallelize across chunks.
    block(i, I_h, T_I_horiz)      # apply to H_FWD and H_BWD
    parallelize(I_h)              # distribute row-tiles across 32 cores

    # Vertical passes (V_FWD, V_BWD):
    #   - columns j are independent; recurrences are only along i.
    #   - tile j into chunks and parallelize across chunks.
    block(j, J_v, T_J_vert)       # apply to V_FWD and V_BWD
    parallelize(J_v)

    #--------------------------------------------------------------
    # 2. Locality-friendly blocking for pointwise stages
    #--------------------------------------------------------------
    # COMB1 and COMB2 are purely pointwise (no recurrences) and
    # can be fully parallelized and vectorized. We use 2D tiling
    # to improve cache locality and expose coarse-grain parallelism.
    block(i, I_c, T_I_comb)       # outer row tiles
    block(j, J_c, T_J_comb)       # outer column tiles
    parallelize(I_c)              # parallel over row tiles
    vectorize(J_c, VEC_W)         # SIMD over contiguous columns inside each tile

    #--------------------------------------------------------------
    # 3. Preserve recurrence order while improving cache behavior
    #--------------------------------------------------------------
    # We avoid parallelizing or vectorizing the recurrence dimensions
    # (inner j in H_FWD/H_BWD, inner i in V_FWD/V_BWD) to preserve
    # the IIR dependencies. Within each tile, the loops still run
    # sequentially in the recurrence direction (enforced by 'seq' and
    # the explicit dependencies), so the mathematical behavior is
    # identical to the original scalar C++ loops.
    #
    # We may still block the recurrence dimension for better cache
    # locality, but only with sequential tiles:
    #   - e.g., in H_FWD/H_BWD, we could apply
    #       block(j, Jh, Jh_size)
    #     without parallelizing Jh, so that j advances in order across
    #     tiles and the scalar recurrence state naturally flows across
    #     tile boundaries.
    #
    # (Omitted here for simplicity; can be enabled as:
    #    block(j, Jh, Jh_size)  # applied only to H_FWD and H_BWD
    #  while keeping Jh sequential.)

    #--------------------------------------------------------------
    # 4. Arithmetic simplifications and scalar hoisting
    #--------------------------------------------------------------
    # - All coefficients (ea, e2a, e_2a, k, a1..a8, b1, b2, c1, c2)
    #   are computed once in COEFFS and treated as loop-invariant
    #   scalars inside the recurrences and combinations.
    # - Division by constants in COEFFS is folded into multiplications
    #   by precomputed reciprocals by the compiler (not shown here).
    # - The pointwise combinations reuse (y1 + y2) directly without
    #   recomputation of any intermediates.
--- END OF MODEL: deriche-02 ---

--- START OF MODEL: deriche-03 ---
domain:
    # Image dimensions follow the original C layout img[W][H]:
    #   i: "row"/slow dimension  (0..W-1)
    #   j: "column"/fast dimension (0..H-1, contiguous in memory)
    i: dim in [0, W)
    j: dim in [0, H)

data:
    # Row-major layout: j is the innermost/contiguous dimension.
    imgIn[i, j]:  in  DATA_TYPE = (i, j) -> i * H + j
    imgOut[i, j]: out DATA_TYPE = (i, j) -> i * H + j

    # Temporaries for the two directional recurrences.
    y1[i, j]: tmp DATA_TYPE = (i, j) -> i * H + j
    y2[i, j]: tmp DATA_TYPE = (i, j) -> i * H + j

parameters:
    alpha: DATA_TYPE        # filter parameter
    c1:    DATA_TYPE        # first pointwise combination scale  (here: 1)
    c2:    DATA_TYPE        # second pointwise combination scale (here: 1)

computation:
    # ------------------------------------------------------------
    # 0. Scalar coefficient setup (independent of i,j).
    #    Matches the Polybench Deriche kernel.
    # ------------------------------------------------------------
    ea   = exp(-alpha)
    e2a  = exp( DATA_TYPE(2.0) * alpha)
    e_2a = exp(-DATA_TYPE(2.0) * alpha)

    k = (DATA_TYPE(1.0) - ea) * (DATA_TYPE(1.0) - ea) /
        (DATA_TYPE(1.0) + DATA_TYPE(2.0) * alpha * ea - e2a)

    a1 = k
    a5 = k

    a2 = k * ea * (alpha - DATA_TYPE(1.0))
    a6 = a2

    a3 = k * ea * (alpha + DATA_TYPE(1.0))
    a7 = a3

    a4 = -k * e_2a
    a8 = a4

    b1 = pow(DATA_TYPE(2.0), -alpha)
    b2 = -e_2a

    # ------------------------------------------------------------
    # 1. Horizontal forward recursion (left -> right).
    #    For each row i, compute along j with loop-carried deps:
    #      y1[i,j] = a1*x[i,j] + a2*x[i,j-1] + b1*y1[i,j-1] + b2*y1[i,j-2]
    #    with boundary conditions x[i,-1]=0, y1[i,-1]=y1[i,-2]=0.
    # ------------------------------------------------------------
    H_FWD:
    for i in [0, W):
        # Row-local state (scalars) for recurrence.
        ym1 = DATA_TYPE(0)   # y1[i, j-1]
        ym2 = DATA_TYPE(0)   # y1[i, j-2]
        xm1 = DATA_TYPE(0)   # x[i, j-1]

        for j in seq([0, H)):   # sequential over j due to recurrence
            x_ij = imgIn[i, j]
            y_ij = a1 * x_ij + a2 * xm1 + b1 * ym1 + b2 * ym2
            y1[i, j] = y_ij

            xm1 = x_ij
            ym2 = ym1
            ym1 = y_ij

    # ------------------------------------------------------------
    # 2. Horizontal backward recursion (right -> left).
    #    For each row i, compute along j with loop-carried deps:
    #      y2[i,j] = a3*x[i,j+1] + a4*x[i,j+2]
    #               + b1*y2[i,j+1] + b2*y2[i,j+2]
    #    with boundary x[i,H]=x[i,H+1]=0, y2[i,H]=y2[i,H+1]=0.
    # ------------------------------------------------------------
    H_BWD:
    for i in [0, W):
        yp1 = DATA_TYPE(0)   # y2[i, j+1]
        yp2 = DATA_TYPE(0)   # y2[i, j+2]
        xp1 = DATA_TYPE(0)   # x[i, j+1]
        xp2 = DATA_TYPE(0)   # x[i, j+2]

        for j in seq([0, H)):   # traverse j from H-1 down to 0, but sequential
            jj = H - 1 - j      # jj is the actual column index, descending
            y_ij = a3 * xp1 + a4 * xp2 + b1 * yp1 + b2 * yp2
            y2[i, jj] = y_ij

            xp2 = xp1
            xp1 = imgIn[i, jj]
            yp2 = yp1
            yp1 = y_ij

    # ------------------------------------------------------------
    # 3. First pointwise combination (no dependencies between pixels):
    #       imgOut[i,j] = c1 * (y1[i,j] + y2[i,j])
    #    This is purely elementwise; can be fully parallelized/vectorized.
    # ------------------------------------------------------------
    COMB1:
    for i in [0, W), j in [0, H):
        imgOut[i, j] = c1 * (y1[i, j] + y2[i, j])

    # ------------------------------------------------------------
    # 4. Vertical forward recursion (top -> bottom).
    #    Now work on columns of imgOut, again as 1D IIR per column:
    #      y1[i,j] = a5*x[i,j] + a6*x[i-1,j] + b1*y1[i-1,j] + b2*y1[i-2,j]
    #    with x[-1,j]=0, y1[-1,j]=y1[-2,j]=0.
    # ------------------------------------------------------------
    V_FWD:
    for j in [0, H):
        tm1 = DATA_TYPE(0)   # x[i-1, j]
        ym1 = DATA_TYPE(0)   # y1[i-1, j]
        ym2 = DATA_TYPE(0)   # y1[i-2, j]

        for i in seq([0, W)):   # sequential over i due to recurrence
            x_ij = imgOut[i, j]
            y_ij = a5 * x_ij + a6 * tm1 + b1 * ym1 + b2 * ym2
            y1[i, j] = y_ij

            tm1 = x_ij
            ym2 = ym1
            ym1 = y_ij

    # ------------------------------------------------------------
    # 5. Vertical backward recursion (bottom -> top).
    #    For each column j:
    #      y2[i,j] = a7*x[i+1,j] + a8*x[i+2,j]
    #               + b1*y2[i+1,j] + b2*y2[i+2,j]
    #    with x[W,j]=x[W+1,j]=0, y2[W,j]=y2[W+1,j]=0.
    # ------------------------------------------------------------
    V_BWD:
    for j in [0, H):
        tp1 = DATA_TYPE(0)   # x[i+1, j]
        tp2 = DATA_TYPE(0)   # x[i+2, j]
        yp1 = DATA_TYPE(0)   # y2[i+1, j]
        yp2 = DATA_TYPE(0)   # y2[i+2, j]

        for i in seq([0, W)):   # traverse i from W-1 down to 0, but sequential
            ii = W - 1 - i
            y_ij = a7 * tp1 + a8 * tp2 + b1 * yp1 + b2 * yp2
            y2[ii, j] = y_ij

            tp2 = tp1
            tp1 = imgOut[ii, j]
            yp2 = yp1
            yp1 = y_ij

    # ------------------------------------------------------------
    # 6. Final pointwise combination:
    #       imgOut[i,j] = c2 * (y1[i,j] + y2[i,j])
    #    Again purely elementwise.
    # ------------------------------------------------------------
    COMB2:
    for i in [0, W), j in [0, H):
        imgOut[i, j] = c2 * (y1[i, j] + y2[i, j])

dependencies:
    # Dataflow between phases for each pixel (i,j).
    for i in [0, W), j in [0, H):
        H_FWD(i, j) -> COMB1(i, j)
        H_BWD(i, j) -> COMB1(i, j)
        COMB1(i, j) -> V_FWD(i, j)
        V_FWD(i, j) -> V_BWD(i, j)
        V_BWD(i, j) -> COMB2(i, j)

optimization:
    # ---------------- Horizontal passes (1 & 2) ----------------
    # Each row i is independent; inner j is a strict recurrence.
    # Parallelize over rows, keep j sequential for correctness.
    parallelize(i)   # apply to H_FWD and H_BWD outer loops over i

    # ---------------- Vertical passes (4 & 5) -------------------
    # Each column j is independent; inner i is a strict recurrence.
    # Parallelize over columns, keep i sequential for correctness.
    parallelize(j)   # apply to V_FWD and V_BWD outer loops over j

    # ---------------- Pointwise combinations (3 & 6) ------------
    # COMB1 and COMB2 are simple elementwise operations with no deps.
    # 1) Tile the 2D domain to improve cache locality.
    #    TI, TJ are tunable tile sizes; reasonable defaults might be
    #    TI = 32 (rows), TJ = 128 (cols) for a large CPU cache.
    block(i, I, 32)      # outer tile index I over rows
    block(j, J, 128)     # outer tile index J over cols

    # 2) Parallelize over row tiles and/or row dimension for good
    #    multi-core utilization on a 32-core machine.
    parallelize(I)

    # 3) Vectorize across the innermost contiguous dimension j
    #    for both COMB1 and COMB2. VJ is vector width; choose
    #    8 or 16 depending on SIMD width and DATA_TYPE size.
    vectorize(j, 16)

    # Notes:
    # - Sequential execution along j in H_FWD/H_BWD and along i in
    #   V_FWD/V_BWD is required to respect the IIR recurrences.
    # - Parallelizing outer dimensions (i for horizontal, j for vertical)
    #   incurs no cross-iteration dependencies and exposes row/column‑
    #   level parallelism ideal for 32–64 hardware threads.
    # - Tiling + vectorization in COMB1/COMB2 improves cache reuse and
    #   uses SIMD for the purely pointwise work (imgOut[i,j] = c*(y1+y2))
    #   while keeping the memory footprint within the original buffers
    #   (no extra large temporaries are introduced).
--- END OF MODEL: deriche-03 ---

--- START OF MODEL: deriche-04 ---
# Optimized model for 2D Deriche filter (Polybench-style), matching the given code.
# Indices:
#   i : row index in [0, W)
#   j : column index in [0, H)
# Layout:
#   All 2D arrays use row‑major layout: j is the fastest‑varying dimension.

domain:
    i: dim in [0, W)       # rows (width W)
    j: dim in [0, H)       # columns (height H)

data:
    # Input image
    imgIn[i, j]: in num_t = (i, j) -> i * H + j          # row-major

    # Output image (also used as intermediate between the horizontal and vertical stages)
    imgOut[i, j]: inout num_t = (i, j) -> i * H + j      # row-major

    # Internal line buffers for recursive passes
    y1[i, j]: tmp num_t = (i, j) -> i * H + j           # row-major
    y2[i, j]: tmp num_t = (i, j) -> i * H + j           # row-major

parameters:
    # Primary scalar parameter
    alpha: num_t

    # Filter coefficients, all scalars computed once from alpha (outside the main loops)
    # (same formulas as in the C++ code; numeric values are not expanded here)
    ea:   num_t       # exp(-alpha)
    e2a:  num_t       # exp( 2*alpha)
    e_2a: num_t       # exp(-2*alpha)
    k:    num_t

    a1: num_t
    a2: num_t
    a3: num_t
    a4: num_t
    a5: num_t
    a6: num_t
    a7: num_t
    a8: num_t

    b1: num_t
    b2: num_t

    c1: num_t        # = 1 in the given implementation
    c2: num_t        # = 1 in the given implementation

    # Tuning constants for parallel/blocked execution of the pointwise combinations
    BLOCK_I: int     # tile size along i for pointwise stages (e.g., 32 or 64)
    BLOCK_J: int     # tile size along j for pointwise stages (e.g., 128)
    VEC_J:   int     # vector width along j for pointwise stages (e.g., 8 for AVX2/float)

computation:

    # ------------------------------------------------------------------
    # Initialization of imgIn (matches init_array): 
    #   imgIn[i][j] = ((313*i + 991*j) % 65536) / 65535.0f;
    # imgOut is not used before being fully overwritten, but we can
    # initialize it to 0 without affecting correctness.
    # ------------------------------------------------------------------
    INIT_IN:
        for i in [0, W), in seq(i):
            for j in [0, H), in seq(j):
                val_int = (313 * i + 991 * j) mod 65536
                imgIn[i, j] = cast(num_t, val_int) / cast(num_t, 65535.0)

    INIT_OUT:
        for i in [0, W), in seq(i):
            for j in [0, H), in seq(j):
                imgOut[i, j] = 0

    # ------------------------------------------------------------------
    # 1) Horizontal forward recursion (left -> right along j).
    #     For each row i, y1[i, j] depends on previous j in the same row.
    #     Rows are independent of each other.
    #     y1_h_fwd[i, j]  ~  a1 * imgIn[i, j] + a2 * imgIn[i, j-1] + ...
    # ------------------------------------------------------------------
    HFWD:
        for i in [0, W), in seq(i):                # rowwise, sequential within each row
            ym1 = 0        # y[i, j-1]
            ym2 = 0        # y[i, j-2]
            xm1 = 0        # x[i, j-1] = imgIn[i, j-1]
            for j in [0, H), in seq(j):            # left -> right
                x_ij = imgIn[i, j]
                y_ij = a1 * x_ij +
                       a2 * xm1 +
                       b1 * ym1 +
                       b2 * ym2
                y1[i, j] = y_ij

                xm1 = x_ij
                ym2 = ym1
                ym1 = y_ij

    # ------------------------------------------------------------------
    # 2) Horizontal backward recursion (right -> left along j).
    #     For each row i, y2[i, j] depends on future j in that row.
    #     Use an explicit reverse traversal via an auxiliary iterator jr.
    # ------------------------------------------------------------------
    HBWD:
        for i in [0, W), in seq(i):
            yp1 = 0        # y[i, j+1]
            yp2 = 0        # y[i, j+2]
            xp1 = 0        # x[i, j+1] = imgIn[i, j+1]
            xp2 = 0        # x[i, j+2] = imgIn[i, j+2]
            for jr in [0, H), in seq(jr):          # jr goes 0..H-1, map to j = H-1-jr
                j = H - 1 - jr
                y_ij = a3 * xp1 +
                       a4 * xp2 +
                       b1 * yp1 +
                       b2 * yp2
                y2[i, j] = y_ij

                xp2 = xp1
                xp1 = imgIn[i, j]
                yp2 = yp1
                yp1 = y_ij

    # ------------------------------------------------------------------
    # 3) First pointwise combination:
    #       imgOut[i, j] = c1 * (y1[i, j] + y2[i, j])
    #     This is purely elementwise and has no loop-carried dependencies.
    # ------------------------------------------------------------------
    COMB1:
        for i in [0, W):
            for j in [0, H):
                imgOut[i, j] = c1 * (y1[i, j] + y2[i, j])

    # ------------------------------------------------------------------
    # 4) Vertical forward recursion (top -> bottom along i).
    #     For each column j, y1[i, j] depends on previous i in that column.
    #     Columns are independent of each other.
    # ------------------------------------------------------------------
    VFWD:
        for j in [0, H), in seq(j):                # columnwise, sequential within each column
            tm1 = 0        # x[i-1, j] = imgOut[i-1, j]
            ym1 = 0        # y[i-1, j]
            ym2 = 0        # y[i-2, j]
            for i in [0, W), in seq(i):            # top -> bottom
                x_ij = imgOut[i, j]
                y_ij = a5 * x_ij +
                       a6 * tm1 +
                       b1 * ym1 +
                       b2 * ym2
                y1[i, j] = y_ij

                tm1 = x_ij
                ym2 = ym1
                ym1 = y_ij

    # ------------------------------------------------------------------
    # 5) Vertical backward recursion (bottom -> top along i).
    #     For each column j, y2[i, j] depends on future i in that column.
    # ------------------------------------------------------------------
    VBWD:
        for j in [0, H), in seq(j):
            tp1 = 0        # x[i+1, j] = imgOut[i+1, j]
            tp2 = 0        # x[i+2, j] = imgOut[i+2, j]
            yp1 = 0        # y[i+1, j]
            yp2 = 0        # y[i+2, j]
            for ir in [0, W), in seq(ir):          # ir goes 0..W-1, map to i = W-1-ir
                i = W - 1 - ir
                y_ij = a7 * tp1 +
                       a8 * tp2 +
                       b1 * yp1 +
                       b2 * yp2
                y2[i, j] = y_ij

                tp2 = tp1
                tp1 = imgOut[i, j]
                yp2 = yp1
                yp1 = y_ij

    # ------------------------------------------------------------------
    # 6) Final pointwise combination:
    #       imgOut[i, j] = c2 * (y1[i, j] + y2[i, j])
    #     Again purely elementwise.
    # ------------------------------------------------------------------
    COMB2:
        for i in [0, W):
            for j in [0, H):
                imgOut[i, j] = c2 * (y1[i, j] + y2[i, j])

dependencies:
    # Data dependencies along the recursive directions (for clarity only;
    # they follow directly from the sequential inner loops):
    #
    # Horizontal forward:
    #   HFWD at (i, j) depends on HFWD at (i, j-1) for j > 0.
    #
    # Horizontal backward:
    #   HBWD at (i, j) depends on HBWD at (i, j+1) for j < H-1.
    #
    # Vertical forward:
    #   VFWD at (i, j) depends on VFWD at (i-1, j) for i > 0.
    #
    # Vertical backward:
    #   VBWD at (i, j) depends on VBWD at (i+1, j) for i < W-1.
    #
    # COMB1 and COMB2 are pointwise and only depend on matching y1,y2 elements.

optimization:

    # --------------------------------------------------------------
    # Parallelization of independent outer loops
    # --------------------------------------------------------------
    # Horizontal passes: each row i is independent, recursion is only along j.
    # Safe to parallelize across rows in HFWD and HBWD.
    HFWD: parallelize(i)
    HBWD: parallelize(i)

    # Vertical passes: each column j is independent, recursion is only along i.
    # Safe to parallelize across columns in VFWD and VBWD.
    VFWD: parallelize(j)
    VBWD: parallelize(j)

    # --------------------------------------------------------------
    # Cache-friendly blocking and SIMD vectorization for pointwise stages
    # (COMB1 and COMB2 have no loop-carried dependencies)
    # --------------------------------------------------------------

    # For COMB1, tile the (i, j) iteration space and parallelize tiles along i.
    # BLOCK_I, BLOCK_J are tunable based on cache size: e.g., BLOCK_I=32, BLOCK_J=256.
    COMB1: block(i, I1, BLOCK_I)          # I1 = outer tile index in i
    COMB1: block(j, J1, BLOCK_J)          # J1 = outer tile index in j
    COMB1: hoist(I1)                      # move tile loop I1 outermost in COMB1
    COMB1: hoist(J1)                      # next outer
    COMB1: parallelize(I1)                # distribute tiles in i over threads
    # Inside each tile, make j the innermost loop and SIMD‑vectorize it.
    COMB1: interchange(j, i)              # ensure inner loop is over j (contiguous)
    COMB1: vectorize(j, VEC_J)            # SIMD over columns within a row

    # Apply the same tiling and vectorization strategy to COMB2.
    COMB2: block(i, I2, BLOCK_I)
    COMB2: block(j, J2, BLOCK_J)
    COMB2: hoist(I2)
    COMB2: hoist(J2)
    COMB2: parallelize(I2)
    COMB2: interchange(j, i)
    COMB2: vectorize(j, VEC_J)

    # --------------------------------------------------------------
    # Notes:
    # - No blocking or vectorization is applied along the recursive
    #   directions (inner j in HFWD/HBWD, inner i in VFWD/VBWD) to
    #   preserve the IIR dependencies.
    # - Parallelization is only across independent rows/columns.
    # - The additional storage (y1, y2) matches the original code; no
    #   extra large buffers are introduced, keeping memory overhead
    #   within 50% of the baseline.
