	gemm.tile(j, i, jo, io, jj, ii, 16, 16, TailStrategy::GuardWithIf)
	    .reorder(jo, io, ii, jj);

	gemm.update()
	    .tile(j, i, jo, io, jj, ii, 16, 16, TailStrategy::GuardWithIf)
	    .split(k, ko, ki, 16, TailStrategy::GuardWithIf)
	    .reorder(ko, jo, io, ii, ki, jj);

	C_param.set(C);
	A_param.set(A);
	B_param.set(B);

	// compile the kernel to machine code
	gemm.compile_jit();

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	gemm.realize(C);

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results
	using namespace std::string_literals;
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		for (int i = 0; i < ni; i++) {
			for (int j = 0; j < nj; j++) {
				std::cerr << C(j, i) << '\n';
			}
		}
	}

	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}
