    for (int i = n - 1; i >= 0; --i) {
        for (int j = i + 1; j < n; ++j) {
            i_param.set(i);
            j_param.set(j);

            // cell() is a zero-dimensional Func. Realize to a scalar Buffer.
            Halide::Buffer<num_t> result = cell.realize();
            num_t new_val = result(); // zero-dimensional Buffer: operator() with 0 args

            // Write back to our DP table.
            table(j, i) = new_val;
        }
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the live-out data (upper triangle of the table),
    // similar to the PolyBench print_array() function.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        int t = 0;
        for (int i = 0; i < n; ++i) {
            for (int j = i; j < n; ++j) {
                if (t % 20 == 0) {
                    std::cerr << '\n';
                }
                std::cerr << table(j, i) << ' ';
                ++t;
            }
        }
        std::cerr << '\n';
    }

    // Print kernel execution time (in seconds, to 6 decimal places).
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
